import { loadCanon } from "../compiler/loadCanon.js";

// 260903-MAX-049 (generated-docs-report-zero-circles-for-self-hosting-spoke,
// from MAX-043's basher generated-doc audit): both generated docs enumerated a
// spoke's circles by reading ONE hardcoded directory,
// `<spokeDir>/canon/circles` -- generateClaudeMd.js's own
// `loadYamlEntities(path.join(spokeDir, "canon", "circles"), "circle")` and
// generateAmbassadorBrief.js's identical call. That path is real on an adopted
// spoke and only there. harness-factory, the real self-hosting spoke, has no
// `canon/circles` directory at all -- its 38 live circles live in
// `reference/circles/` -- so both of its generated docs reported an empty
// toolbox ("## Live circles (0)", "0 live circle(s):") while 28 real hook
// matchers fired on it every session, and the brief printed a fabricated
// mechanism for it ("self-hosting spokes compile canon directly; no scaffolded
// circles") that is the opposite of what compileSelf.js really does.
//
// The compiler already knew better. It never looks for `canon/circles` either:
// loadCanon() walks the WHOLE spoke root (SKIP_DIRS and all) and compileSelf.js
// takes the circles it really binds straight off that result --
// `result.entities.filter((e) => e.kind === "circle")`. So the fix is not a
// second directory guess (and explicitly not copying reference/circles into
// canon/circles, which would create exactly the second driftable copy both
// generators' own headers forbid): it is to ask the compiler's own loader,
// authored once here and imported by both generators, so a doc's circle list
// and the settings.json those circles compile into can never again disagree
// about what this spoke's toolbox is.

/**
 * The circle entities in an already-loaded entity list -- the one authored copy
 * of the kind filter compileSelf.js binds hooks from, so the generated docs and
 * the generated settings.json read the same set by construction.
 */
export function circleEntities(entities) {
  return entities.filter((e) => e.kind === "circle");
}

/**
 * Every circle the real compiler loads for this spoke, wherever in the spoke
 * those files really sit (`canon/circles` on an adopted spoke,
 * `reference/circles` on the self-hosting one, anywhere else a future spoke
 * puts them). Same loader, same skip rules, same result as `compile(spokeDir)`
 * -- deliberately not a reimplementation with its own path assumptions.
 */
export function loadSpokeCircles(spokeDir) {
  return circleEntities(loadCanon(spokeDir));
}

/**
 * This spoke's live circles, sorted by name -- what a generated doc renders.
 * Both generators call exactly this, so their counts cannot drift from each
 * other or from the compiler's.
 */
export function liveSpokeCircles(spokeDir) {
  return loadSpokeCircles(spokeDir)
    .filter((c) => c.status === "live")
    .sort((a, b) => a.name.localeCompare(b.name));
}
