export function checkSpokeDrift(spokeDir) {
  const profilePath = path.join(spokeDir, "canon", "profile.yaml");
  if (!fs.existsSync(profilePath)) {
    return { spokeDir, ok: false, reason: `no canon/profile.yaml found -- not a scaffolded instance, or profile is missing` };
  }
  const profile = yaml.load(fs.readFileSync(profilePath, "utf8"));

  const scratchDir = fs.mkdtempSync(path.join(os.tmpdir(), "spoke-drift-"));
  try {
    // lug scaffolded-spoke-ships-schedule-circles-with-no-wheel-clock: the
    // recompile is judged against this spoke's own clock, so the circles a
    // cut would exclude here are excluded from the expectation too.
    scaffoldInstance(scratchDir, profile, { clockRoot: spokeDir });
    const diff = diffDirs(path.join(scratchDir, "canon", "circles"), path.join(spokeDir, "canon", "circles"));
